# Some error with banner flows. We'll debug by printing all outputs between prompts.
def get_draw():
    io = remote('crypto.chal.csaw.io', 5000)
    output = b''
    while b'How many tickets' not in output:
        output += io.recv(1024, timeout=5)
    io.sendline(b'1')
    ticket_output = b''
    ticket_prompts = []
    for _ in range(6):
        while b'ticket 1:' not in ticket_output:
            chunk = io.recv(1024, timeout=5)
            if not chunk:
                break
            ticket_output += chunk
        ticket_prompts.append(ticket_output.decode())
        io.sendline(b'1')
        ticket_output = b''
    # Now read all further output until either Draw 0 or EOF
    post_ticket_output = b''
    while True:
        try:
            chunk = io.recv(1024, timeout=5)
            if not chunk:
                break
            post_ticket_output += chunk
            if b'Draw 0:' in post_ticket_output:
                break
        except EOFError:
            break
    content = post_ticket_output.decode(errors='replace')
    for line in content.split('\n'):
        if 'Draw 0:' in line:
            io.close()
            return line.strip()
    io.close()
    return None

draws = []
for _ in range(2):
    draw = get_draw()
    if draw:
        draws.append(draw)
